ALTER TABLE library_content_nodes_v2 DROP CONSTRAINT IF EXISTS library_content_nodes_v2_content_type_check;
ALTER TABLE library_content_nodes_v2 ADD CONSTRAINT library_content_nodes_v2_content_type_check CHECK (content_type IN ('hebrew_main_text','spanish_main_text','english_main_text','spanish_translation','english_translation','main_explanation','rabbi_natan_commentary','rebbe_nachman_teaching','halakhic_body','story_text','prayer_text','editorial_note','translator_note','numbered_footnote','numbered_footnote_continuation','probable_footnote_continuation','unlinked_footnote_fragment','citable_unlinked_satellite','citable_unlinked_note','marginal_source','marginal_commentary','marginal_rabbinic_commentary','rashbam_commentary','source_commentary','talmudic_source','biblical_source','zohar_source','midrash_source','biblical_quote','talmudic_quote','midrash_quote','zohar_quote','halakhic_source_quote','kabbalistic_source_quote','source_reference','cross_reference','glossary_entry','diagram','diagram_caption','summary','index_entry','page_header','section_marker','appendix_material','appendix_diagram','bibliography','copyright','dedication','blank','unknown_textual_satellite','unknown'));

CREATE OR REPLACE VIEW library_investigative_nodes_v2 AS
SELECT n.content_node_id,u.document_id,u.canonical_ref AS section,a.pdf_page_number,a.printed_page_number,a.page_label,n.content_type,n.node_role,n.authority_level,n.link_status,n.review_status,n.ai_confidence AS confidence,n.literal_text,n.normalized_text,n.metadata_json->>'source_or_commentator' AS source_or_commentator,n.citable
FROM library_content_nodes_v2 n JOIN library_content_units_v2 u ON u.content_unit_id=n.content_unit_id JOIN library_page_anchors_v2 a ON a.page_anchor_id=n.page_anchor_id;
